/* Differential test of checker/rt/tmpl_bits.c against native x86-64 code (cq-w0-tmpl-bits).
 *
 * For every op and width in native.h (generated by gen_native.py, compiled by clang-19 -O1), the
 * op the family registered with cqe_register_op is run on the same operands as the native LLVM
 * operation and the W-bit results are compared. Operand classes per width: edge values (0, 1, 2, 3,
 * -1, -2, MIN, MIN+1, MAX, MAX-1, alternating patterns, every single bit), fp specials of
 * f16/f32/f64/f80 as bit patterns at width W, a seeded random set, and every input when the
 * operands total at most 21 bits. Shift amounts: 0 .. 2W+2, multiples of W, the edge values and
 * random ones.
 *
 * CR §2 rows where native LLVM is poison (shl/lshr/ashr with an amount >= W) are checked against
 * the table instead: the tab_ wrapper, which takes `urem k, W` natively before the shift. fshl/fshr
 * and ctlz/cttz(0) are defined by LLVM itself (amount mod W, is_zero_poison = false gives W), so
 * native agrees with the table and they are compared natively; ctlz/cttz(0) = W is also asserted
 * directly. bswap exists only for W a multiple of 16; at every other width the op must reject.
 *
 * The harness supplies the two cqe.h functions the family calls (cqe_register_op, cqe_fail), so
 * the test runs without the evaluator core. Operands are passed with garbage above bit W (a narrow
 * literal is read as its low W bits, CR §1.2) and, for ternary ops, with aliased storage (112
 * fshr(%5, %5, %6)).
 */
#include <inttypes.h>
#include <stdarg.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "cqe.h"
#include "native.h"

/* ---- cqe.h stand-ins ---- */
static struct { char op[24]; cqe_op_fn fn; } reg[64];
static int nreg, nfail;
static char lastfail[512];

void cqe_register_op(const char *op, cqe_op_fn fn) {
  if (nreg == 64) {
    fprintf(stderr, "too many registrations\n");
    exit(2);
  }
  snprintf(reg[nreg].op, sizeof reg[nreg].op, "%s", op);
  reg[nreg++].fn = fn;
}
void cqe_fail(const char *fmt, ...) {
  va_list ap;
  va_start(ap, fmt);
  vsnprintf(lastfail, sizeof lastfail, fmt, ap);
  va_end(ap);
  ++nfail;
}
static cqe_op_fn lookup(const char *op) {
  cqe_op_fn f = NULL;
  int n = 0;
  for (int i = 0; i < nreg; ++i)
    if (!strcmp(reg[i].op, op))
      f = reg[i].fn, ++n;
  return n == 1 ? f : NULL;
}

/* ---- values ---- */
#define MAXW 4 /* words for the widest test width, 200 bits */
typedef struct { uint64_t w[MAXW]; } val;

static uint64_t rng = 0x9E3779B97F4A7C15ull; /* fixed seed */
static uint64_t next(void) {
  rng ^= rng << 13;
  rng ^= rng >> 7;
  rng ^= rng << 17;
  return rng;
}
static uint32_t nwords(uint32_t W) { return (W + 63) / 64; }
static void canon(val *v, uint32_t W) {
  for (uint32_t i = 0; i < MAXW; ++i) {
    if (i * 64 >= W)
      v->w[i] = 0;
    else if (W - i * 64 < 64)
      v->w[i] &= ((uint64_t)1 << (W - i * 64)) - 1;
  }
}
static val from_u64(uint64_t x, uint32_t W) {
  val v = {{x}};
  canon(&v, W);
  return v;
}
static val ones(uint32_t W) {
  val v;
  memset(&v, 0xFF, sizeof v);
  canon(&v, W);
  return v;
}
static void setbit(val *v, uint32_t i) { v->w[i / 64] |= (uint64_t)1 << (i % 64); }
static val add_small(val v, int64_t d, uint32_t W) { /* v + d mod 2^W */
  uint64_t ext = d < 0 ? ~(uint64_t)0 : 0;
  /* simple, obviously-correct bit-serial add */
  val r = {{0}};
  int c = 0;
  for (uint32_t i = 0; i < W; ++i) {
    int a = (int)(v.w[i / 64] >> (i % 64) & 1);
    int b = i < 64 ? (int)((uint64_t)d >> i & 1) : (int)(ext & 1);
    int s = a + b + c;
    if (s & 1)
      setbit(&r, i);
    c = s >> 1;
  }
  return r;
}
static int cmpv(const val *a, const val *b) { return memcmp(a->w, b->w, sizeof a->w); }
static int ge_u32(const val *k, uint32_t W) { /* k >= W, unsigned */
  for (uint32_t i = 1; i < MAXW; ++i)
    if (k->w[i])
      return 1;
  return k->w[0] >= W;
}

typedef struct { val *v; int n, cap; } vset;
static void push(vset *s, val v, uint32_t W) {
  canon(&v, W);
  for (int i = 0; i < s->n; ++i)
    if (!cmpv(&s->v[i], &v))
      return;
  if (s->n == s->cap) {
    s->cap = s->cap ? 2 * s->cap : 64;
    s->v = realloc(s->v, (size_t)s->cap * sizeof *s->v);
  }
  s->v[s->n++] = v;
}
static val rnd(uint32_t W) {
  val v;
  for (int i = 0; i < MAXW; ++i)
    v.w[i] = next();
  canon(&v, W);
  return v;
}

static void edges(vset *s, uint32_t W, int single_bits) {
  val z = {{0}}, mn = {{0}}, mx;
  setbit(&mn, W - 1);
  mx = ones(W);
  mx.w[(W - 1) / 64] &= ~((uint64_t)1 << ((W - 1) % 64));
  canon(&mx, W);
  push(s, z, W);
  push(s, from_u64(1, W), W);
  push(s, from_u64(2, W), W);
  push(s, from_u64(3, W), W);
  push(s, ones(W), W);
  push(s, add_small(ones(W), -1, W), W);
  push(s, mn, W);
  push(s, add_small(mn, 1, W), W);
  push(s, mx, W);
  push(s, add_small(mx, -1, W), W);
  val p5, pa;
  memset(&p5, 0x55, sizeof p5);
  memset(&pa, 0xAA, sizeof pa);
  push(s, p5, W);
  push(s, pa, W);
  if (single_bits)
    for (uint32_t i = 0; i < W; ++i) {
      val b = {{0}};
      setbit(&b, i);
      push(s, b, W);
    }
}

static void fp_specials(vset *s, uint32_t W) {
  static const uint64_t f16[] = {0x0000, 0x8000, 0x7C00, 0xFC00, 0x7E00, 0x7C01, 0x0001, 0x03FF, 0x3C00};
  static const uint64_t f32[] = {0x00000000, 0x80000000, 0x7F800000, 0xFF800000, 0x7FC00000,
                                 0xFFC00000, 0x00000001, 0x007FFFFF, 0x3F800000};
  static const uint64_t f64[] = {0, 0x8000000000000000ull, 0x7FF0000000000000ull, 0xFFF0000000000000ull,
                                 0x7FF8000000000000ull, 0xFFF8000000000000ull, 1, 0x000FFFFFFFFFFFFFull,
                                 0x3FF0000000000000ull};
  static const uint64_t f80[][2] = {{0, 0},
                                    {0, 0x8000},
                                    {0x8000000000000000ull, 0x7FFF},
                                    {0x8000000000000000ull, 0xFFFF},
                                    {0xC000000000000000ull, 0x7FFF},
                                    {0xC000000000000000ull, 0xFFFF},
                                    {0x4000000000000000ull, 0x7FFF},
                                    {1, 0},
                                    {0x8000000000000000ull, 0x3FFF}};
  for (size_t i = 0; i < sizeof f16 / sizeof *f16; ++i)
    push(s, from_u64(f16[i], W), W);
  for (size_t i = 0; i < sizeof f32 / sizeof *f32; ++i)
    push(s, from_u64(f32[i], W), W);
  for (size_t i = 0; i < sizeof f64 / sizeof *f64; ++i)
    push(s, from_u64(f64[i], W), W);
  for (size_t i = 0; i < sizeof f80 / sizeof *f80; ++i) {
    val v = {{f80[i][0], f80[i][1]}};
    push(s, v, W);
  }
}

static vset values(uint32_t W, int exhaustive, int single_bits, int nrand) {
  vset s = {0};
  if (exhaustive) {
    s.cap = s.n = (int)((uint64_t)1 << W); /* distinct by construction: no dedup */
    s.v = malloc((size_t)s.cap * sizeof *s.v);
    for (uint64_t x = 0; x < ((uint64_t)1 << W); ++x)
      s.v[x] = from_u64(x, W);
    return s;
  }
  edges(&s, W, single_bits);
  fp_specials(&s, W);
  for (int i = 0; i < nrand; ++i)
    push(&s, rnd(W), W);
  return s;
}

static vset amounts(uint32_t W) {
  vset s = {0};
  for (uint32_t k = 0; k <= 2 * W + 2; ++k)
    push(&s, from_u64(k, W), W);
  for (uint32_t m = 3; m <= 9; ++m)
    push(&s, from_u64((uint64_t)m * W, W), W);
  push(&s, from_u64(64, W), W);
  push(&s, from_u64(65, W), W);
  push(&s, from_u64(256 + 3, W), W);
  edges(&s, W, 0);
  for (int i = 0; i < 48; ++i)
    push(&s, rnd(W), W);
  for (int i = 0; i < 16; ++i) { /* a large amount whose residue mod W is random */
    val v = rnd(W);
    push(&s, v, W);
  }
  return s;
}

/* ---- running one case ---- */
static long n_native, n_table, n_mismatch, n_reject;
static int first_only; /* --first: exit 1 at the first disagreement (the mutant run) */

static int run_ours(cqe_op_fn fn, const char *op, uint32_t W, const val *ops, int arity, int alias, val *out,
                    uint32_t out_bits) {
  cqe_tname t;
  memset(&t, 0, sizeof t);
  snprintf(t.op, sizeof t.op, "%s", op);
  snprintf(t.w, sizeof t.w, "i%u", W);
  /* operands: the W-bit value plus garbage above bit W and one extra word of garbage */
  uint64_t buf[3][MAXW + 1];
  cqe_val args[3];
  for (int i = 0; i < arity; ++i) {
    uint32_t nw = nwords(W);
    for (uint32_t j = 0; j <= nw && j <= MAXW; ++j)
      buf[i][j] = next();
    for (uint32_t j = 0; j < nw; ++j) {
      uint64_t lowmask = (W - 64 * j >= 64) ? ~(uint64_t)0 : (((uint64_t)1 << (W - 64 * j)) - 1);
      buf[i][j] = (buf[i][j] & ~lowmask) | (ops[i].w[j] & lowmask);
    }
    args[i].bits = W;
    args[i].kind = 'i';
    args[i].nw = nw + 1;
    args[i].w = buf[i];
  }
  if (alias && arity == 3 && !cmpv(&ops[0], &ops[1]))
    args[1].w = args[0].w; /* one rail in two operand slots */
  uint64_t ow[MAXW];
  for (int j = 0; j < MAXW; ++j)
    ow[j] = 0xDEADBEEFDEADBEEFull; /* the op must write every word */
  cqe_val o = {out_bits, 'i', nwords(W), ow};
  int rc = fn(&t, args, arity, &o);
  if (rc == 0 && (o.bits != out_bits || o.kind != 'i' || o.nw != nwords(W) || o.w != ow)) {
    fprintf(stderr, "%s_i%u changed the core-owned out fields\n", op, W);
    rc = -2;
  }
  memset(out, 0, sizeof *out);
  memcpy(out->w, ow, nwords(W) * sizeof(uint64_t));
  return rc;
}

static void check_case(const struct row *r, cqe_op_fn fn, const val *ops, int alias) {
  uint32_t W = r->w;
  val in[3] = {{{0}}, {{0}}, {{0}}};
  for (int i = 0; i < r->arity; ++i)
    in[i] = ops[i];
  int table = r->amount >= 0 && r->tab && ge_u32(&ops[r->amount], W);
  nat_fn nf = table ? r->tab : r->nat;
  val want;
  memset(&want, 0, sizeof want);
  nf(in[0].w, in[1].w, in[2].w, want.w);
  canon(&want, W);
  val got;
  int rc = run_ours(fn, r->op, W, ops, r->arity, alias, &got, W);
  val gotc = got;
  canon(&gotc, W);
  table ? ++n_table : ++n_native;
  if (rc != 0 || cmpv(&got, &want) || cmpv(&got, &gotc)) {
    if (++n_mismatch <= 20) {
      fprintf(stderr, "MISMATCH %s_i%u (%s) rc=%d", r->op, W, table ? "table" : "native", rc);
      for (int i = 0; i < r->arity; ++i) {
        fprintf(stderr, " op%d=", i);
        for (int j = (int)nwords(W) - 1; j >= 0; --j)
          fprintf(stderr, "%016" PRIx64, ops[i].w[j]);
      }
      fprintf(stderr, " want=");
      for (int j = (int)nwords(W) - 1; j >= 0; --j)
        fprintf(stderr, "%016" PRIx64, want.w[j]);
      fprintf(stderr, " got=");
      for (int j = (int)nwords(W) - 1; j >= 0; --j)
        fprintf(stderr, "%016" PRIx64, got.w[j]);
      fprintf(stderr, "%s%s\n", rc ? " fail: " : "", rc ? lastfail : "");
    }
    if (first_only)
      exit(1);
  }
}

static int expect_reject(cqe_op_fn fn, const char *what, const char *op, const char *w, int nargs, uint32_t W,
                         uint32_t out_bits) {
  cqe_tname t;
  memset(&t, 0, sizeof t);
  snprintf(t.op, sizeof t.op, "%s", op);
  snprintf(t.w, sizeof t.w, "%s", w);
  uint64_t a[MAXW] = {1, 0, 0, 0}, b[MAXW] = {1, 0, 0, 0}, c[MAXW] = {1, 0, 0, 0}, ow[MAXW] = {0};
  cqe_val args[3] = {{W, 'i', nwords(W ? W : 1), a}, {W, 'i', nwords(W ? W : 1), b}, {W, 'i', nwords(W ? W : 1), c}};
  cqe_val o = {out_bits, 'i', nwords(out_bits ? out_bits : 1), ow};
  int f0 = nfail;
  int rc = fn(&t, args, nargs, &o);
  if (rc == 0 || nfail != f0 + 1) {
    fprintf(stderr, "NOT REJECTED: %s (%s_%s, %d args): rc=%d\n", what, op, w, nargs, rc);
    if (first_only)
      exit(1);
    return 1;
  }
  ++n_reject;
  return 0;
}

int main(int argc, char **argv) {
  int bad = 0;
  first_only = argc > 1 && !strcmp(argv[1], "--first");
  /* every op registered exactly once */
  for (size_t i = 0; i < sizeof OPS / sizeof *OPS; ++i)
    if (!lookup(OPS[i])) {
      fprintf(stderr, "op %s not registered exactly once\n", OPS[i]);
      ++bad;
    }
  if (nreg != (int)(sizeof OPS / sizeof *OPS)) {
    fprintf(stderr, "registered %d ops, expected %zu\n", nreg, sizeof OPS / sizeof *OPS);
    ++bad;
  }
  if (bad)
    return 1;

  /* first (cheap, and the mutant run stops early): malformed calls are rejected with a violation, never evaluated */
  cqe_op_fn f_and = lookup("and"), f_fshl = lookup("fshl"), f_ctpop = lookup("ctpop");
  bad += expect_reject(f_and, "arity", "and", "i32", 1, 32, 32);
  bad += expect_reject(f_fshl, "arity", "fshl", "i32", 2, 32, 32);
  bad += expect_reject(f_ctpop, "arity", "ctpop", "i32", 2, 32, 32);
  bad += expect_reject(f_and, "fp width", "and", "f32", 2, 32, 32);
  bad += expect_reject(f_and, "zero width", "and", "i0", 2, 1, 1);
  bad += expect_reject(f_and, "result width", "and", "i32", 2, 32, 64);
  { /* an op name this family does not know: CQE_OP_NOT_MINE, no violation, out untouched */
    cqe_tname t;
    memset(&t, 0, sizeof t);
    snprintf(t.op, sizeof t.op, "add");
    snprintf(t.w, sizeof t.w, "i32");
    uint64_t a[1] = {1}, ow[1] = {0};
    cqe_val args[2] = {{32, 'i', 1, a}, {32, 'i', 1, a}}, o = {32, 'i', 1, ow};
    int f0 = nfail;
    if (f_and(&t, args, 2, &o) != 1 || nfail != f0 || ow[0]) {
      fprintf(stderr, "foreign op not declined with CQE_OP_NOT_MINE\n");
      if (first_only)
        exit(1);
      ++bad;
    }
  }

  for (size_t ri = 0; ri < sizeof ROWS / sizeof *ROWS; ++ri) {
    const struct row *r = &ROWS[ri];
    cqe_op_fn fn = lookup(r->op);
    uint32_t W = r->w;
    long nat0 = n_native, tab0 = n_table;
    if (!r->nat) { /* bswap at W not a multiple of 16 */
      char w[8];
      snprintf(w, sizeof w, "i%u", W);
      bad += expect_reject(fn, "bswap outside its domain", "bswap", w, 1, W, W);
      printf("%-6s i%-4u rejected (W %% 16 != 0)\n", r->op, W);
      continue;
    }
    val ops[3];
    if (r->arity == 1) {
      vset v = values(W, W <= 21, 1, 512);
      for (int i = 0; i < v.n; ++i) {
        ops[0] = v.v[i];
        check_case(r, fn, ops, 0);
      }
      free(v.v);
      if (!strcmp(r->op, "ctlz") || !strcmp(r->op, "cttz")) { /* CR §2: ctlz(0) = cttz(0) = W */
        val z = {{0}}, got;
        if (run_ours(fn, r->op, W, &z, 1, 0, &got, W) || got.w[0] != W || got.w[1] || got.w[2] || got.w[3]) {
          fprintf(stderr, "%s_i%u(0) != W\n", r->op, W);
          if (first_only)
            exit(1);
          ++bad;
        }
        ++n_table;
      }
    } else if (r->arity == 2) {
      int ex = 2 * W <= 21;
      vset a = values(W, ex, 1, 48);
      vset b = r->amount >= 0 ? (ex ? values(W, 1, 0, 0) : amounts(W)) : values(W, ex, 1, 48);
      for (int i = 0; i < a.n; ++i)
        for (int j = 0; j < b.n; ++j) {
          ops[0] = a.v[i];
          ops[1] = b.v[j];
          check_case(r, fn, ops, 0);
        }
      for (int i = 0; i < 4096; ++i) { /* random pairs */
        ops[0] = rnd(W);
        ops[1] = rnd(W);
        check_case(r, fn, ops, 0);
      }
      free(a.v);
      free(b.v);
    } else {
      int ex = 3 * W <= 21;
      vset a = values(W, ex, 0, 8);
      vset k = ex ? values(W, 1, 0, 0) : amounts(W);
      for (int i = 0; i < a.n; ++i)
        for (int j = 0; j < a.n; ++j)
          for (int l = 0; l < k.n; ++l) {
            ops[0] = a.v[i];
            ops[1] = a.v[j];
            ops[2] = k.v[l];
            check_case(r, fn, ops, i == j);
          }
      for (int i = 0; i < 4096; ++i) {
        ops[0] = rnd(W);
        ops[1] = (i & 3) ? rnd(W) : ops[0];
        ops[2] = rnd(W);
        check_case(r, fn, ops, (i & 3) == 0);
      }
      free(a.v);
      free(k.v);
    }
    printf("%-6s i%-4u native %8ld  table %7ld\n", r->op, W, n_native - nat0, n_table - tab0);
  }

  printf("tmpl-bits: rows %zu, native comparisons %ld, table comparisons %ld, rejections %ld, mismatches %ld\n",
         sizeof ROWS / sizeof *ROWS, n_native, n_table, n_reject, n_mismatch);
  return (bad || n_mismatch) ? 1 : 0;
}
